data.client-sdk-quickstart-go#Client SDK Quic:
Install the SDK:
go get github.com/nanoDFS/client-sdk Upload and download files securely:
package main import ( "fmt" "log" "github.com/nanoDFS/client-sdk/crypto" "github.com/nanoDFS/client-sdk/fs" ) func main() { // Generate or load client encryption key cryptoKey := crypto.DefaultCryptoKey() client := fs.NewFileSystem() // Upload a file to PandaFS (automatically chunked, encrypted, and replicated) fileID, userID, err := client.Upload(cryptoKey, "./dataset.tar.gz") if err != nil { log.Fatalf("Failed to upload file: %v", err) } fmt.Printf("Uploaded successfully! FileID: %s, UserID: %s\n", fileID, userID) // Download and decrypt the file err = client.Download(fileID, userID, cryptoKey, "./downloads/dataset_restored.tar.gz") if err != nil { log.Fatalf("Failed to download file: %v", err) } fmt.Println("File downloaded and verified successfully!") }
